        a = rng.randint(0, nb - w)
        kind = rng.choice(['store', 'store', 'load', 'load', 'xchg', 'fence'])
        if kind in ('store', 'xchg'):
            prog.append([kind, a, w, rng.randrange(1 << (8 * w))])
        elif kind == 'load':
            prog.append(['load', a, w])
        else:
            prog.append(['fence'])
    return prog

