import random, sys
sys.path.insert(0, '/app')
from crosscheck import naive2, key_set
from main import solve

rng = random.Random(888)
bad = 0; checked = 0
for _ in range(600):
    nbytes = rng.randint(1, 8)
    mem = [rng.randrange(256) for _ in range(nbytes)]
    threads = []
    for _ in range(rng.randint(1, 3)):
        prog = []
        for _ in range(rng.randint(0, 4)):
            kind = rng.choice(['store', 'load', 'fence', 'xchg'])
            w = rng.choice([1, 2, 4])
            if w > nbytes:
                continue
            a = rng.randint(0, nbytes - w)
            if kind in ('store', 'xchg'):
                prog.append([kind, a, w, rng.randrange(1 << (8 * w))])
            elif kind == 'load':
                prog.append(['load', a, w])
            else:
                prog.append(['fence'])
        threads.append(prog)
    while sum(len(p) for p in threads) > 10:
        for i, p in enumerate(threads):
            if p and sum(len(q) for q in threads) > 10:
                threads[i] = p[:-1]
    req = {'memory': mem, 'threads': threads}
    if not all(0 <= op[1] and op[1] + op[2] <= nbytes
               for p in threads for op in p if op[0] in ('store', 'load', 'xchg')):
        continue
    checked += 1
    if key_set(solve(req)['outcomes']) != naive2(req):
        bad += 1
        print('MISMATCH', req)
print('final full-state-BFS cross-check: checked=%d mismatches=%d' % (checked, bad))
